CREATE TABLE IF NOT EXISTS media_assets (id text PRIMARY KEY, mime text NOT NULL, data bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
UPDATE site_content SET document=jsonb_set(document,'{summary}',to_jsonb('Fullstack-разработчик с сильной стороной во frontend. Создаю интерфейсы на React и Next.js, работаю с серверной логикой и продолжаю углублять знания в backend.'::text)) WHERE document->>'summary'='Frontend-разработчик. Создаю веб-интерфейсы на React и Next.js, разбираюсь в дизайне и развиваюсь в backend.';

UPDATE site_content SET document=jsonb_set(document,'{bio,0}',to_jsonb('Я Дарчиев Хетаг Олегович, fullstack-разработчик с фокусом на frontend. Работаю с React и Next.js, стилизую интерфейсы с помощью Tailwind CSS, CSS и SCSS. В backend есть практические знания, которые продолжаю развивать.'::text)) WHERE document->'bio'->>0='Я Дарчиев Хетаг Олегович. Моё основное направление — frontend-разработка. Работаю с React и Next.js, стилизую интерфейсы с помощью Tailwind CSS, CSS и SCSS.';
